//! Golden-output integration tests.
//!
//! Every fixture `.s` file below, and every string in every `EXPECTED_*`
//! array, was generated by running the ACTUAL Python `ufa_baremetal`
//! package (the one this crate ports) against these exact fixtures, in
//! the same session this port was written, via a small script that
//! rendered each verdict and escaped it as a Rust string literal
//! programmatically — not transcribed by hand. That matters: an earlier
//! hand-written draft of this file got the expected line for the K02
//! spill-imbalance fixture wrong (it assumed index 0 would be the K02
//! FAIL, when K01 fires on the same fixture and sorts first in registry
//! order) until it was checked against the real output. The scripted
//! generation removes that whole class of mistake.
//!
//! Fixtures are embedded as string literals (rather than living in
//! `tests/fixtures/*.s` and being read at runtime) so `cargo test` has
//! zero filesystem dependency beyond the crate itself.

use ufa_baremetal_core::k_invariants::{self, Ctx};
use ufa_baremetal_core::parse_s::assert_parse_complete;

fn run_all_checks(text: &str, file: &str) -> Vec<String> {
    assert_parse_complete(text, file).expect("fixture must parse completely");
    let ctx = Ctx::with_file(file);
    let mut out = Vec::new();
    for (_, check) in k_invariants::K_REGISTRY {
        for v in check(text, &ctx) {
            out.push(v.render());
        }
    }
    out
}

fn assert_matches(text: &str, file: &str, expected: &[&str]) {
    let out = run_all_checks(text, file);
    assert_eq!(out, expected, "\n--- full actual output for {file} ---\n{}", out.join("\n\n"));
}

const GOOD_FN: &str = "\
.text
.global good_fn
.type good_fn, %function
good_fn:
    // params: [('a', 'INT32'), ('b', 'U64')] ret: INT64
    STP X29, X30, [SP, #-16]!
    SUB SP, SP, #16
    MOV X29, SP
    STR W0, [X29, #8]    // spill param a
    STR X1, [X29, #0]    // spill param b
    LDRSW X9, [X29, #8]
    LDR X10, [X29, #0]
    ADD X0, X9, X10
    ADD SP, SP, #16
    LDP X29, X30, [SP], #16
    RET
.size good_fn, . - good_fn
";

const EXPECTED_GOOD_FN: &[&str] = &[
    "[K01 PASS] good_fn.s:4 in good_fn() — frame, spill discipline, and offset alignment OK",
    "[K02 PASS] good_fn.s:4 in good_fn() — scratch-register spill discipline OK (0 push/pop pair(s))",
    "[K03 PASS] good_fn.s:4 in good_fn() — type-width load/store discipline OK (2 typed offset(s))",
    "[K04 PASS] good_fn.s:4 in good_fn() — sign-extension before signed compare OK (0 signed-branch site(s))",
    "[K05 NOT_APPLICABLE] good_fn.s — K05 applies only to *_boot.s / *_init.s files; this file is not a boot-protocol handoff point.",
    "[K06 NOT_APPLICABLE] good_fn.s — No data globals in this file; K06 N/A.",
];

#[test]
fn good_fn_passes_every_applicable_check() {
    assert_matches(GOOD_FN, "good_fn.s", EXPECTED_GOOD_FN);
}

