const K02_SPILL_IMBALANCE: &str = "\
.text
.global nested_binop
.type nested_binop, %function
nested_binop:
    // params: [] ret: VOID
    STP X29, X30, [SP, #-16]!
    SUB SP, SP, #16
    MOV X29, SP
    STR X9, [SP, #-16]!
    STR X10, [SP, #-16]!
    LDR X10, [SP], #16
    ADD SP, SP, #16
    LDP X29, X30, [SP], #16
    RET
.size nested_binop, . - nested_binop
";

// Note: K01 also fires on this fixture (it independently checks push/pop
// balance too), and K01 sorts before K02 in registry order -- so index 0
// here is a K01 FAIL, not K02. Getting this wrong by assumption rather
// than checking is exactly the mistake described in the module doc.
const EXPECTED_K02_SPILL_IMBALANCE: &[&str] = &[
    "[K01 FAIL] k02_spill_imbalance.s:9 in nested_binop() — unbalanced register-spill stack writes: 2 `STR Xn, [SP, #-16]!` push(es) vs 1 `LDR Xn, [SP], #16` pop(s)\n    fix: Every `STR Xn, [SP, #-16]!` must be matched by a `LDR Xn, [SP], #16` within the same function. See Bug #12, Bug #23 — the nested-binop save/restore pattern.",
    "[K02 FAIL] k02_spill_imbalance.s:10 in nested_binop() — unbalanced scratch-register spill: 2 `STR Xn, [SP, #-16]!` vs 1 `LDR Xn, [SP], #16`. Bug #12-class regression.\n    fix: Every nested-binop spill `STR Xn, [SP, #-16]!` must be matched by a `LDR Xn, [SP], #16` later in the same function, before the function returns.",
    "[K02 FAIL] k02_spill_imbalance.s:13 in nested_binop() — function exit reached with non-zero spill depth (1); SP would be off by 16 bytes after RET\n    fix: Drain all outstanding `STR Xn, [SP, #-16]!` before the function's `LDP X29, X30, [SP], #16` epilogue.",
    "[K03 PASS] k02_spill_imbalance.s:4 in nested_binop() — type-width load/store discipline OK (0 typed offset(s))",
    "[K04 PASS] k02_spill_imbalance.s:4 in nested_binop() — sign-extension before signed compare OK (0 signed-branch site(s))",
    "[K05 NOT_APPLICABLE] k02_spill_imbalance.s — K05 applies only to *_boot.s / *_init.s files; this file is not a boot-protocol handoff point.",
    "[K06 NOT_APPLICABLE] k02_spill_imbalance.s — No data globals in this file; K06 N/A.",
];

#[test]
fn k02_catches_spill_imbalance() {
    assert_matches(K02_SPILL_IMBALANCE, "k02_spill_imbalance.s", EXPECTED_K02_SPILL_IMBALANCE);
}

